502→
503→        // 8. Only unpin CIDs of pruned versions (excess beyond max 10)
504→        // Old CIDs stay pinned as version history (VER-01)
505→        for (const prunedCid of prunedCids) {
506→          unpinFromIpfs(prunedCid).catch(() => {});
507→        }
508→
509→        // Refresh quota
510→        useQuotaStore.getState().fetchQuota();
511→
512→        setState({ isLoading: false, error: null });
513→      } catch (err) {
514→        const error = err instanceof Error ? err.message : 'Failed to update file';
515→        setState({ isLoading: false, error });
516→        throw err;
517→      }
518→    },
519→    []
520→  );
521→
522→  return {
523→    ...state,
524→    addFile: handleAddFile,
525→    addFiles: handleAddFiles,
