167→
168→        // Also add the new folder node to the store (with its decrypted keys)
169→        const newFolderNode: FolderNode = {
170→          id: folder.id,
171→          name: folder.name,
172→          ipnsName: folder.ipnsName,
173→          parentId: parentFolder.id,
174→          children: [],
175→          isLoaded: true,
176→          isLoading: false,
177→          sequenceNumber: 0n,
178→          folderKey,
179→          ipnsPrivateKey,
180→        };
181→        useFolderStore.getState().setFolder(newFolderNode);
182→
183→        // Post-create: re-wrap new subfolder key for share recipients (fire-and-forget)
184→        reWrapForRecipients({
185→          folderIpnsName: parentFolder.ipnsName,
186→          folders: useFolderStore.getState().folders,
187→          currentFolderId: parentFolder.id,
188→          newItems: [{ keyType: 'folder', itemId: folder.id, plaintextKey: folderKey }],
189→        }).catch((err) => {
190→          console.warn('[share] Post-create subfolder re-wrapping failed:', err);
191→        });
192→
193→        setState({ isLoading: false, error: null });
194→        return folder;
195→      } catch (err) {
196→        const error = err instanceof Error ? err.message : 'Failed to create folder';
197→        setState({ isLoading: false, error });
198→        throw err;
199→      }
200→    },
201→    []
202→  );
203→
204→  /**
205→   * Rename a file or folder.
206→   *
207→   * @param itemId - ID of item to rename
208→   * @param itemType - 'file' or 'folder'
209→   * @param newName - New name
210→   * @param parentId - Parent folder ID
211→   */
212→  const handleRename = useCallback(
213→    async (
214→      itemId: string,
215→      itemType: 'file' | 'folder',
216→      newName: string,
217→      parentId: string
218→    ): Promise<void> => {
219→      setState({ isLoading: true, error: null });
220→      try {
221→        const getParentFolder = () => {
222→          const freshState = useFolderStore.getState();
223→          return parentId === 'root'
224→            ? getRootFolderState(useVaultStore.getState(), freshState.folders)
225→            : freshState.folders[parentId];
226→        };
227→
228→        const parentFolder = getParentFolder();
229→        if (!parentFolder) throw new Error('Parent folder not found');
230→
231→        const performRename = async () => {
232→          const freshParent = getParentFolder();
233→          if (!freshParent) throw new Error('Parent folder not found');
234→          if (itemType === 'folder') {
235→            await folderService.renameFolder({
236→              folderId: itemId,
237→              newName,
238→              parentFolderState: freshParent,
239→            });
240→          } else {
241→            await folderService.renameFile({
242→              fileId: itemId,
243→              newName,
244→              parentFolderState: freshParent,
245→            });
246→          }
247→        };
248→
249→        try {
250→          await performRename();
251→        } catch (err) {
252→          if (!isConflictError(err)) throw err;
253→          useSyncStore.getState().setConflict('Folder updated by another device, re-syncing...');
254→          await resyncFolder(parentFolder.ipnsName, parentFolder.id);
255→          await new Promise((r) => setTimeout(r, 100 + Math.random() * 400));
256→          try {
257→            await performRename();
258→            useSyncStore.getState().clearConflict();
259→          } catch (retryErr) {
260→            useSyncStore.getState().clearConflict();
261→            if (isConflictError(retryErr)) {
262→              throw new Error('Conflict persists after re-sync. Please try again.');
263→            }
264→            throw retryErr;
265→          }
266→        }
267→
268→        if (itemType === 'folder') {
269→          // Update local folder state name
270→          useFolderStore.getState().updateFolderName(itemId, newName);
271→        }
272→
273→        // Update parent's children with new name using fresh state
274→        const freshParent = getParentFolder();
275→        if (freshParent) {
276→          const updatedChildren = freshParent.children.map((child) => {
277→            if (child.id === itemId) {
278→              return { ...child, name: newName, modifiedAt: Date.now() };
279→            }
280→            return child;
281→          });
282→          useFolderStore.getState().updateFolderChildren(parentId, updatedChildren);
283→        }
284→
285→        setState({ isLoading: false, error: null });
286→      } catch (err) {
287→        const error = err instanceof Error ? err.message : 'Failed to rename';
288→        setState({ isLoading: false, error });
289→        throw err;
290→      }
291→    },
292→    []
293→  );
294→
295→  /**
296→   * Move a file or folder to a different parent.
297→   *
298→   * @param itemId - ID of item to move
299→   * @param itemType - 'file' or 'folder'
300→   * @param sourceParentId - Current parent folder ID
301→   * @param destParentId - Destination parent folder ID
302→   */
303→  const handleMove = useCallback(
304→    async (
305→      itemId: string,
306→      itemType: 'file' | 'folder',
307→      sourceParentId: string,
308→      destParentId: string
309→    ): Promise<void> => {
310→      setState({ isLoading: true, error: null });
311→      try {
312→        const getSourceFolder = () => {
313→          const freshState = useFolderStore.getState();
314→          return sourceParentId === 'root'
315→            ? getRootFolderState(useVaultStore.getState(), freshState.folders)
316→            : freshState.folders[sourceParentId];
317→        };
318→
319→        const getDestFolder = () => {
320→          const freshState = useFolderStore.getState();
321→          return destParentId === 'root'
322→            ? getRootFolderState(useVaultStore.getState(), freshState.folders)
323→            : freshState.folders[destParentId];
324→        };
325→
326→        const sourceFolder = getSourceFolder();
327→        const destFolder = getDestFolder();
328→        if (!sourceFolder || !destFolder) {
329→          throw new Error('Source or destination folder not found');
330→        }
331→
332→        const performMove = async () => {
333→          const freshSource = getSourceFolder();
334→          const freshDest = getDestFolder();
335→          if (!freshSource || !freshDest) throw new Error('Source or destination folder not found');
336→          const folders = useFolderStore.getState().folders;
337→          if (itemType === 'folder') {
338→            await folderService.moveFolder({
339→              folderId: itemId,
340→              sourceFolderState: freshSource,
341→              destFolderState: freshDest,
342→              folders,
343→            });
344→          } else {
345→            await folderService.moveFile({
346→              fileId: itemId,
347→              sourceFolderState: freshSource,
348→              destFolderState: freshDest,
349→            });
350→          }
351→        };
352→
353→        try {
354→          await performMove();
355→        } catch (err) {
356→          if (!isConflictError(err)) throw err;
357→          useSyncStore.getState().setConflict('Folder updated by another device, re-syncing...');
358→          // Re-sync both source and destination folders
359→          await Promise.all([
360→            resyncFolder(sourceFolder.ipnsName, sourceFolder.id),
361→            sourceFolder.id !== destFolder.id
362→              ? resyncFolder(destFolder.ipnsName, destFolder.id)
363→              : Promise.resolve(),
364→          ]);
365→          await new Promise((r) => setTimeout(r, 100 + Math.random() * 400));
366→          try {
367→            await performMove();
368→            useSyncStore.getState().clearConflict();
369→          } catch (retryErr) {
370→            useSyncStore.getState().clearConflict();
371→            if (isConflictError(retryErr)) {
372→              throw new Error('Conflict persists after re-sync. Please try again.');
373→            }
374→            throw retryErr;
375→          }
376→        }
377→
378→        if (itemType === 'folder') {
379→          // Update the moved folder's parentId in local state
380→          const freshFolders = useFolderStore.getState().folders;
381→          const movedFolder = freshFolders[itemId];
382→          if (movedFolder) {
383→            useFolderStore.getState().setFolder({
384→              ...movedFolder,
385→              parentId: destParentId,
386→            });
387→          }
388→        }
389→
390→        // Update source folder's children (remove item)
391→        const freshSource = getSourceFolder();
392→        if (freshSource) {
393→          const updatedSourceChildren = freshSource.children.filter((c) => c.id !== itemId);
394→          useFolderStore.getState().updateFolderChildren(sourceParentId, updatedSourceChildren);
395→        }
396→
397→        // Update dest folder's children (add item)
398→        const freshDest = getDestFolder();
399→        const originalSource = getSourceFolder();
400→        const movedItem = originalSource?.children.find((c) => c.id === itemId);
401→        if (movedItem && freshDest) {
402→          const updatedDestChildren = [
403→            ...freshDest.children,
404→            { ...movedItem, modifiedAt: Date.now() },
405→          ];
406→          useFolderStore.getState().updateFolderChildren(destParentId, updatedDestChildren);
407→        }
408→
409→        setState({ isLoading: false, error: null });
410→      } catch (err) {
411→        const error = err instanceof Error ? err.message : 'Failed to move';
412→        setState({ isLoading: false, error });
413→        throw err;
414→      }
415→    },
416→    []
417→  );
418→
419→  /**
420→   * Move multiple files/folders to a destination in a single batch.
421→   *
422→   * Uses add-before-remove pattern. Publishes IPNS once for the destination
423→   * and once for the source (2 total), regardless of how many items are moved.
424→   *
425→   * @param items - Array of { id, type } to move
426→   * @param sourceParentId - Current parent folder ID (all items must share the same parent)
427→   * @param destParentId - Destination parent folder ID
428→   */
429→  const handleMoveItems = useCallback(
430→    async (
431→      items: Array<{ id: string; type: 'file' | 'folder' }>,
432→      sourceParentId: string,
433→      destParentId: string
434→    ): Promise<void> => {
435→      setState({ isLoading: true, error: null });
436→      try {
437→        const getSourceFolder = () => {
438→          const freshState = useFolderStore.getState();
439→          return sourceParentId === 'root'
440→            ? getRootFolderState(useVaultStore.getState(), freshState.folders)
441→            : freshState.folders[sourceParentId];
442→        };
443→        const getDestFolder = () => {
444→          const freshState = useFolderStore.getState();
445→          return destParentId === 'root'
446→            ? getRootFolderState(useVaultStore.getState(), freshState.folders)
447→            : freshState.folders[destParentId];
448→        };
449→
450→        const sourceFolder = getSourceFolder();
451→        const destFolder = getDestFolder();
452→
453→        if (!sourceFolder || !destFolder) {
454→          throw new Error('Source or destination folder not found');
455→        }
456→
457→        const itemIds = new Set(items.map((i) => i.id));
458→        const movedChildren = sourceFolder.children.filter((c) => itemIds.has(c.id));
459→        const now = Date.now();
460→
461→        // Validate all items (do this once before the retry loop)
462→        const batchNames = new Set<string>();
463→        for (const child of movedChildren) {
464→          // Intra-batch duplicate name check
465→          if (batchNames.has(child.name)) {
466→            throw new Error(`Multiple selected items share the name "${child.name}"`);
467→          }
468→          batchNames.add(child.name);
469→
470→          // Name collision check against destination
471→          const nameExists = destFolder.children.some((c) => c.name === child.name);
472→          if (nameExists) {
473→            throw new Error(`An item named "${child.name}" already exists in the destination`);
474→          }
475→
476→          if (child.type === 'folder') {
477→            // Prevent moving folder into itself or descendant
478→            const folders = useFolderStore.getState().folders;
479→            if (folderService.isDescendantOf(destFolder.id, child.id, folders)) {
480→              throw new Error(`Cannot move "${child.name}" into itself or its subfolder`);
481→            }
482→
483→            // Depth limit check
484→            const destDepth = folderService.getDepth(destFolder.id, folders);
485→            const subtreeDepth = folderService.calculateSubtreeDepth(child.id, folders);
486→            if (destDepth + 1 + subtreeDepth > MAX_FOLDER_DEPTH) {
487→              throw new Error(
488→                `Cannot move "${child.name}": would exceed maximum folder depth of ${MAX_FOLDER_DEPTH}`
489→              );
490→            }
491→          }
492→        }
493→
494→        const performBatchMove = async (): Promise<{
495→          destSeq: bigint;
496→          sourceSeq: bigint;
497→          destChildren: FolderNode['children'];
498→          sourceChildren: FolderNode['children'];
499→        }> => {
500→          const freshSource = getSourceFolder();
501→          const freshDest = getDestFolder();
502→          if (!freshSource || !freshDest) throw new Error('Source or destination folder not found');
503→
504→          // Rebuild moved children from fresh source state
505→          const freshMoved = freshSource.children.filter((c) => itemIds.has(c.id));
506→
507→          // ADD all to destination FIRST (add-before-remove pattern)
508→          const destChildren = [
509→            ...freshDest.children,
510→            ...freshMoved.map((c) => ({ ...c, modifiedAt: now })),
511→          ];
512→
513→          const { newSequenceNumber: destSeq } = await folderService.updateFolderMetadata({
514→            folderId: freshDest.id,
515→            children: destChildren,
516→            folderKey: freshDest.folderKey,
517→            ipnsPrivateKey: freshDest.ipnsPrivateKey,
518→            ipnsName: freshDest.ipnsName,
519→            sequenceNumber: freshDest.sequenceNumber,
520→          });
521→
522→          // REMOVE all from source AFTER destination confirmed
523→          const sourceChildren = freshSource.children.filter((c) => !itemIds.has(c.id));
524→
525→          const { newSequenceNumber: sourceSeq } = await folderService.updateFolderMetadata({
526→            folderId: freshSource.id,
527→            children: sourceChildren,
528→            folderKey: freshSource.folderKey,
529→            ipnsPrivateKey: freshSource.ipnsPrivateKey,
530→            ipnsName: freshSource.ipnsName,
531→            // Re-read sequence in case source === dest parent was updated above
532→            sequenceNumber: freshSource.id === freshDest.id ? destSeq : freshSource.sequenceNumber,
533→          });
534→
535→          return { destSeq, sourceSeq, destChildren, sourceChildren };
536→        };
537→
538→        let result: Awaited<ReturnType<typeof performBatchMove>>;
539→        try {
540→          result = await performBatchMove();
541→        } catch (err) {
542→          if (!isConflictError(err)) throw err;
543→          useSyncStore.getState().setConflict('Folder updated by another device, re-syncing...');
544→          await Promise.all([
545→            resyncFolder(sourceFolder.ipnsName, sourceFolder.id),
546→            sourceFolder.id !== destFolder.id
547→              ? resyncFolder(destFolder.ipnsName, destFolder.id)
548→              : Promise.resolve(),
549→          ]);
550→          await new Promise((r) => setTimeout(r, 100 + Math.random() * 400));
551→          try {
552→            result = await performBatchMove();
553→            useSyncStore.getState().clearConflict();
554→          } catch (retryErr) {
555→            useSyncStore.getState().clearConflict();
556→            if (isConflictError(retryErr)) {
557→              throw new Error('Conflict persists after re-sync. Please try again.');
558→            }
559→            throw retryErr;
560→          }
561→        }
562→
563→        // Update local state
564→        const store = useFolderStore.getState();
565→        store.updateFolderChildren(sourceParentId, result.sourceChildren);
566→        store.updateFolderChildren(destParentId, result.destChildren);
567→        store.updateFolderSequence(destParentId, result.destSeq);
568→        store.updateFolderSequence(sourceParentId, result.sourceSeq);
569→
570→        for (const item of items) {
571→          if (item.type === 'folder') {
572→            const movedFolder = useFolderStore.getState().folders[item.id];
573→            if (movedFolder) {
574→              store.setFolder({ ...movedFolder, parentId: destParentId });
575→            }
576→          }
577→        }
578→
579→        setState({ isLoading: false, error: null });
580→      } catch (err) {
581→        const error = err instanceof Error ? err.message : 'Failed to move items';
582→        setState({ isLoading: false, error });
583→        throw err;
584→      }
585→    },
586→    []
587→  );
588→
589→  /**
590→   * Delete a file or folder.
591→   *
592→   * @param itemId - ID of item to delete
593→   * @param itemType - 'file' or 'folder'
594→   * @param parentId - Parent folder ID
595→   */
596→  const handleDelete = useCallback(
597→    async (itemId: string, itemType: 'file' | 'folder', parentId: string): Promise<void> => {
598→      setState({ isLoading: true, error: null });
599→      try {
600→        const getParentFolder = () => {
601→          const freshState = useFolderStore.getState();
602→          return parentId === 'root'
603→            ? getRootFolderState(useVaultStore.getState(), freshState.folders)
604→            : freshState.folders[parentId];
605→        };
606→
607→        const parentFolder = getParentFolder();
608→        if (!parentFolder) throw new Error('Parent folder not found');
609→
610→        const performDelete = async () => {
611→          const freshParent = getParentFolder();
612→          if (!freshParent) throw new Error('Parent folder not found');
613→          if (itemType === 'folder') {
614→            const folders = useFolderStore.getState().folders;
615→            await folderService.deleteFolder({
616→              folderId: itemId,
617→              parentFolderState: freshParent,
618→              getFolderState: (id) => folders[id],
619→              unpinCid: unpinFromIpfs,
620→            });
621→          } else {
622→            await folderService.deleteFileFromFolder({
623→              fileId: itemId,
624→              parentFolderState: freshParent,
625→            });
626→          }
627→        };
628→
629→        try {
630→          await performDelete();
631→        } catch (err) {
632→          if (!isConflictError(err)) throw err;
633→          useSyncStore.getState().setConflict('Folder updated by another device, re-syncing...');
634→          await resyncFolder(parentFolder.ipnsName, parentFolder.id);
635→          await new Promise((r) => setTimeout(r, 100 + Math.random() * 400));
636→          try {
637→            await performDelete();
638→            useSyncStore.getState().clearConflict();
639→          } catch (retryErr) {
640→            useSyncStore.getState().clearConflict();
641→            if (isConflictError(retryErr)) {
642→              throw new Error('Conflict persists after re-sync. Please try again.');
643→            }
644→            throw retryErr;
645→          }
646→        }
647→
648→        if (itemType === 'folder') {
649→          // Remove folder from local state
650→          useFolderStore.getState().removeFolder(itemId);
651→        }
652→
653→        // Update parent's children (remove item) using fresh state
654→        const freshParent = getParentFolder();
655→        if (freshParent) {
656→          const updatedChildren = freshParent.children.filter((c) => c.id !== itemId);
657→          useFolderStore.getState().updateFolderChildren(parentId, updatedChildren);
658→        }
659→
660→        setState({ isLoading: false, error: null });
661→      } catch (err) {
662→        const error = err instanceof Error ? err.message : 'Failed to delete';
663→        setState({ isLoading: false, error });
664→        throw err;
665→      }
666→    },
667→    []
668→  );
669→
670→  /**
671→   * Delete multiple files/folders in a single IPNS publish.
672→   *
673→   * Removes all items from parent's children array, collects CIDs to unpin,
674→   * then publishes metadata and IPNS once for the entire batch.
675→   *
676→   * @param items - Array of { id, type } to delete
677→   * @param parentId - Parent folder ID (all items must share the same parent)
678→   */
679→  const handleDeleteItems = useCallback(
680→    async (
681→      items: Array<{ id: string; type: 'file' | 'folder' }>,
682→      parentId: string
683→    ): Promise<void> => {
684→      setState({ isLoading: true, error: null });
685→      try {
686→        const getParentFolder = () => {
687→          const freshState = useFolderStore.getState();
688→          return parentId === 'root'
689→            ? getRootFolderState(useVaultStore.getState(), freshState.folders)
690→            : freshState.folders[parentId];
691→        };
692→
693→        const parentFolder = getParentFolder();
694→        if (!parentFolder) throw new Error('Parent folder not found');
695→
696→        const itemIds = new Set(items.map((i) => i.id));
697→
698→        // Collect nested folder IDs to remove from store
699→        // In v2, file children are FilePointers (no inline CID). File IPNS/TEE
700→        // enrollments will expire naturally (24h IPNS lifetime). Phase 14 adds cleanup.
701→        const folderIdsToRemove: string[] = [];
702→
703→        const collectFolderIds = (folderId: string) => {
704→          folderIdsToRemove.push(folderId);
705→          const folders = useFolderStore.getState().folders;
706→          const folder = folders[folderId];
707→          if (!folder) return;
708→          for (const child of folder.children) {
709→            if (child.type === 'folder') {
710→              collectFolderIds(child.id);
711→            }
712→          }
713→        };
714→
715→        for (const item of items) {
716→          if (item.type === 'folder') {
717→            collectFolderIds(item.id);
718→          }
719→        }
720→
721→        const performBatchDelete = async (): Promise<typeof parentFolder.children> => {
722→          const freshParent = getParentFolder();
723→          if (!freshParent) throw new Error('Parent folder not found');
724→
725→          // Remove all items from parent's children in one pass
726→          const updatedChildren = freshParent.children.filter((c) => !itemIds.has(c.id));
727→
728→          // Single IPNS publish for the entire batch
729→          await folderService.updateFolderMetadata({
730→            folderId: freshParent.id,
731→            children: updatedChildren,
732→            folderKey: freshParent.folderKey,
733→            ipnsPrivateKey: freshParent.ipnsPrivateKey,
734→            ipnsName: freshParent.ipnsName,
735→            sequenceNumber: freshParent.sequenceNumber,
736→          });
737→
738→          return updatedChildren;
739→        };
740→
741→        let updatedChildren: typeof parentFolder.children;
742→        try {
743→          updatedChildren = await performBatchDelete();
744→        } catch (err) {
745→          if (!isConflictError(err)) throw err;
746→          useSyncStore.getState().setConflict('Folder updated by another device, re-syncing...');
747→          await resyncFolder(parentFolder.ipnsName, parentFolder.id);
748→          await new Promise((r) => setTimeout(r, 100 + Math.random() * 400));
749→          try {
750→            updatedChildren = await performBatchDelete();
751→            useSyncStore.getState().clearConflict();
752→          } catch (retryErr) {
753→            useSyncStore.getState().clearConflict();
754→            if (isConflictError(retryErr)) {
755→              throw new Error('Conflict persists after re-sync. Please try again.');
756→            }
757→            throw retryErr;
758→          }
759→        }
760→
761→        // Update local state -- remove all nested folders from store
762→        const store = useFolderStore.getState();
763→        store.updateFolderChildren(parentId, updatedChildren);
764→        for (const folderId of folderIdsToRemove) {
765→          store.removeFolder(folderId);
766→        }
767→
768→        setState({ isLoading: false, error: null });
769→      } catch (err) {
770→        const error = err instanceof Error ? err.message : 'Failed to delete items';
771→        setState({ isLoading: false, error });
772→        throw err;
773→      }
774→    },
775→    []
776→  );
777→
778→  return {
779→    ...state,
780→    createFolder: handleCreate,
781→    renameItem: handleRename,
782→    moveItem: handleMove,
783→    moveItems: handleMoveItems,
784→    deleteItem: handleDelete,
785→    deleteItems: handleDeleteItems,
786→  };
787→}
788→

