+        //    On 409 conflict, re-sync the parent folder and retry once.
+        const performAddFile = async (): Promise<{
+          filePointer: FilePointer;
+          newSequenceNumber: bigint;
+        }> => {
+          const freshFolders = useFolderStore.getState().folders;
+          const freshVault = useVaultStore.getState();
+          const freshParent =
+            parentId === 'root'
+              ? getRootFolderState(freshVault, freshFolders)
+              : freshFolders[parentId];
+          if (!freshParent) throw new Error('Parent folder not found');
+
+          return folderService.addFileToFolder({
+            parentFolderState: freshParent,
+            fileId,
+            name: fileData.originalName,
+            fileIpnsRecord: ipnsRecord,
+            ipnsPrivateKeyEncrypted,
+          });
+        };
+
+        let addResult: Awaited<ReturnType<typeof performAddFile>>;
+        try {
+          addResult = await performAddFile();
+        } catch (err) {
+          if (!isConflictError(err)) throw err;
+          useSyncStore.getState().setConflict('Folder updated by another device, re-syncing...');
+          await resyncFolder(parentFolder.ipnsName, parentFolder.id);
+          await new Promise((r) => setTimeout(r, 100 + Math.random() * 400));
+          try {
+            addResult = await performAddFile();
+            useSyncStore.getState().clearConflict();
+          } catch (retryErr) {
+            useSyncStore.getState().clearConflict();
+            if (isConflictError(retryErr)) {
+              throw new Error('Conflict persists after re-sync. Please try again.');
+            }
+            throw retryErr;
+          }","path":"apps/web/src/hooks/useFileOperations.ts","commit_id":"ca228845128abd75473b672dade307c102d36a5d","original_commit_id":"ca18f49484cb423c5d2b83bfa9602077c06fbc77","user":{"login":"FSM1","id":12774278,"node_id":"MDQ6VXNlcjEyNzc0Mjc4","avatar_url":"https://avatars.githubusercontent.com/u/12774278?v=4","gravatar_id":"","url":"https://api.github.com/users/FSM1","html_url":"https://github.com/FSM1","followers_url":"https://api.github.com/users/FSM1/followers","following_url":"https://api.github.com/users/FSM1/following{/other_user}","gists_url":"https://api.github.com/users/FSM1/gists{/gist_id}","starred_url":"https://api.github.com/users/FSM1/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/FSM1/subscriptions","organizations_url":"https://api.github.com/users/FSM1/orgs","repos_url":"https://api.github.com/users/FSM1/repos","events_url":"https://api.github.com/users/FSM1/events{/privacy}","received_events_url":"https://api.github.com/users/FSM1/received_events","type":"User","user_view_type":"public","site_admin":false},"body":"Fixed in ca2288451. Restructured the conflict retry block to use `try/finally` for `clearConflict()`. Now `clearConflict()` executes regardless of whether `resyncFolder()` or the retry attempt throws.","created_at":"2026-03-03T14:54:01Z","updated_at":"2026-03-03T14:54:01Z","html_url":"https://github.com/FSM1/cipher-box/pull/253#discussion_r2878746266","pull_request_url":"https://api.github.com/repos/FSM1/cipher-box/pulls/253","_links":{"self":{"href":"https://api.github.com/repos/FSM1/cipher-box/pulls/comments/2878746266"},"html":{"href":"https://github.com/FSM1/cipher-box/pull/253#discussion_r2878746266"},"pull_request":{"href":"https://api.github.com/repos/FSM1/cipher-box/pulls/253"}},"reactions":{"url":"https://api.github.com/repos/FSM1/cipher-box/pulls/comments/2878746266/reactions","total_count":0,"+1":0,"-1":0,"laugh":0,"hooray":0,"confused":0,"heart":0,"rocket":0,"eyes":0},"start_line":116,"origin